// Package models holds persisted control-plane entities and deployment status constants.
// IDs are opaque hex strings generated by the repository layer.
package models

import (
	"strings"
	"time"
)

// Deployment lifecycle values stored in deployments.status (see SQL CHECK constraint).
const (
	DeploymentQueued    = "QUEUED"
	DeploymentBuilding  = "BUILDING"
	DeploymentSuccess   = "SUCCESS"
	DeploymentFailed    = "FAILED"
	DeploymentCancelled = "CANCELLED"
)

const (
	SSLStatusPending = "PENDING"
	SSLStatusActive  = "ACTIVE"
	SSLStatusError   = "ERROR"
)

// GitHubAppMeta is non-sensitive metadata for the singleton GitHub App row.
type GitHubAppMeta struct {
	AppID     int64
	Slug      string
	HTMLURL   string
	ClientID  string
	CreatedAt time.Time
	UpdatedAt time.Time
}

// OnboardingState records the durable completion gates for bootstrap cutover.
type OnboardingState struct {
	GitHubAppComplete        bool
	PlatformDomain           string
	PermanentIngressComplete bool
	BootstrapComplete        bool
	CompletedAt              time.Time
	UpdatedAt                time.Time
}

// GitHubAppSecrets is the sealed material used by the GitHub App client.
type GitHubAppSecrets struct {
	AppID           int64
	Slug            string
	HTMLURL         string
	ClientID        string
	ClientSecretCT  []byte
	PrivateKeyCT    []byte
	WebhookSecretCT []byte
}

// GitHubInstallation mirrors one row in github_app_installations.
type GitHubInstallation struct {
	InstallationID int64
	AccountLogin   string
	AccountType    string
	TargetType     string
	RepoSelection  string
	SuspendedAt    string // RFC3339 or empty
	LastSyncedAt   string // RFC3339 or empty
	CreatedAt      time.Time
}

// Deployment is one build/run attempt for a service environment.
type Deployment struct {
	ID            string `json:"id"`
	ServiceID     string `json:"service_id"`
	EnvironmentID string `json:"environment_id"`
	TriggerKind   string `json:"trigger"`
	Actor         string `json:"actor"`
	CancelledAt   string `json:"cancelled_at,omitempty"`
	RollbackOf    string `json:"rollback_of,omitempty"`
	Branch        string `json:"branch,omitempty"`
	Status        string `json:"status"`
	CommitHash    string `json:"commit_hash"`             // optional; set when known (e.g. post-clone in a later phase)
	LogsPath      string `json:"logs_path,omitempty"`     // optional; build log artifact path
	ImageRef      string `json:"image_ref,omitempty"`     // Docker image reference built for this attempt
	Worktree      string `json:"-"`                       // on-disk clone path is never part of public JSON
	ErrorMessage  string `json:"error_message,omitempty"` // set when Status is DeploymentFailed
	// BuilderKind identifies the selected image builder (railpack or dockerfile); empty for legacy rows.
	BuilderKind string `json:"builder_kind,omitempty"`
	// StackKind is a builder-neutral stable slug (e.g. node, go, dockerfile) for UI icons; empty if not captured.
	StackKind string `json:"stack_kind,omitempty"`
	// StackLabel is a short human summary (e.g. "Node · SPA"); empty if not captured.
	StackLabel string    `json:"stack_label,omitempty"`
	CreatedAt  time.Time `json:"created_at"`
	UpdatedAt  time.Time `json:"updated_at"`
}

// Container records a running Docker instance for a successful deployment.
type Container struct {
	ID                string
	DeploymentID      string
	DockerContainerID string // full ID from Docker Engine
	InternalPort      int    // app port inside the container (matches published port mapping)
	HostPort          int    // published port on 127.0.0.1
	Status            string // e.g. RUNNING
	CreatedAt         time.Time
	UpdatedAt         time.Time
}

// Domain links a public hostname to a service environment.
type Domain struct {
	ID               string
	ApplicationID    string
	EnvironmentID    string
	ServiceID        string
	DomainName       string
	SSLStatus        string
	LastCertMessage  string // operator summary from optional cert poll (not ssl_status / route sync)
	CertCheckedAtRaw string // RFC3339 from DB; empty if never polled
	CreatedAt        time.Time
	UpdatedAt        time.Time
}

// CertCheckedAt returns CertCheckedAtRaw parsed as time, or zero if unset/invalid.
func (d Domain) CertCheckedAt() time.Time {
	raw := strings.TrimSpace(d.CertCheckedAtRaw)
	if raw == "" {
		return time.Time{}
	}
	t, err := time.Parse(time.RFC3339, raw)
	if err != nil {
		return time.Time{}
	}
	return t
}

// DomainRoute is a resolved Caddy route candidate from domain to local upstream port.
type DomainRoute struct {
	Domain
	HostPort int
}

// DeployStepRecord is one persisted deploy or system observability span (SQLite observability UI).
type DeployStepRecord struct {
	DeploymentID  string
	ServiceID     string
	EnvironmentID string
	RequestID     string
	Step          string
	Status        string // ok | failed
	DurationMS    int64
	ErrorCode     string
	StartedAt     time.Time
	EndedAt       time.Time
}

// HTTPRequestRecord is one sampled HTTP request line for the observability UI.
type HTTPRequestRecord struct {
	RequestID     string
	ApplicationID string
	ServiceID     string
	EnvironmentID string
	Method        string
	Path          string
	Status        int
	DurationMS    int64
	StartedAt     time.Time
}
